function normalizeStampLabel(label: string) {
  const trimmed = label.trim().toUpperCase();
  if (trimmed === '--') {
    return '--';
  }

  if (/^\d+$/.test(trimmed)) {
    const parsed = Number.parseInt(trimmed, 10);
    if (parsed >= 1 && parsed <= 222) {
      return String(parsed);
    }
  }

  if (
    /^[A-Z]{1,3}$/.test(trimmed) ||
    /^[A-Z]{1,3}\d{1,4}$/.test(trimmed) ||
    /^\d{1,4}[A-Z]{1,3}$/.test(trimmed)
  ) {
    return trimmed;
  }

  return null;
}

function normalizeTourOrderLabel(label: string) {
  const trimmed = label.trim().toUpperCase();
  if (trimmed === '--') {
    return '--';
  }

  if (/^[A-Z]{1,3}$/.test(trimmed)) {
    return trimmed;
  }

  return null;
}

export function getPreGeneratedMapMarkerImageSource(input: {
  kind: MarkerVisualKind;
  label: string;
}): ImageRequireSource | undefined {
  const sourceMap =
    Platform.OS === 'android' ? MAP_MARKER_IMAGE_SOURCE_BY_KEY_ANDROID : MAP_MARKER_IMAGE_SOURCE_BY_KEY_IOS;

  if (input.kind === 'parking') {
    return sourceMap['parking:P'];
  }

  if (input.kind === 'tour-order') {
    const normalizedTourOrderLabel = normalizeTourOrderLabel(input.label);
    if (!normalizedTourOrderLabel) {
      return undefined;
    }

    return sourceMap[`tour-order:${normalizedTourOrderLabel}`];
  }

  const normalizedStampLabel = normalizeStampLabel(input.label);
  if (!normalizedStampLabel) {
    // Unknown labels should use the runtime text marker fallback.
    return undefined;
  }

  return sourceMap[`${input.kind}:${normalizedStampLabel}`];
}
